const NET = /^net\s*(\d{1,3})$/i;
const ON_RECEIPT = /^due\s+on\s+receipt$/i;

export class InvalidPaymentTermsError extends Error {
  constructor(input: string) {
    super(`Unrecognized payment terms: "${input}"`);
    this.name = 'InvalidPaymentTermsError';
  }
}

/** Parses terms like "net 30" or "due on receipt" into a number of days. */
export function parsePaymentTerms(input: string): number {
  const s = input.trim();
  if (ON_RECEIPT.test(s)) return 0;
  const m = NET.exec(s);
  if (m) {
    const days = Number(m[1]);
    if (days > 0 && days <= 365) return days;
  }
  throw new InvalidPaymentTermsError(input);
}

import { describe, expect, it } from 'vitest';
import { InvalidPaymentTermsError, parsePaymentTerms } from './payment-terms';

describe('parsePaymentTerms', () => {
  it.each([
    ['net 30', 30],
    ['Net45', 45],
    ['NET 7', 7],
    ['  net   60 ', 60],
    ['due on receipt', 0],
    ['Due On Receipt', 0],
  ])('%s -> %i', (input, days) => {
    expect(parsePaymentTerms(input)).toBe(days);
  });

  it.each(['', 'net', 'net 0', 'net 400', 'net -5', '30', 'net 30 days'])('rejects %j', (input) => {
    expect(() => parsePaymentTerms(input)).toThrow(InvalidPaymentTermsError);
  });
});

