import { TrashIcon } from '../../icons';
import { useInvoiceEditorStore } from '@/stores/invoice-editor';
import type { LineItemDraft } from '@/lib/types';

export function LineItemRow({ item }: { item: LineItemDraft }) {
  const update = useInvoiceEditorStore((s) => s.updateLine);
  const remove = useInvoiceEditorStore((s) => s.removeLine);

  return (
    <div className="grid grid-cols-[1fr_6rem_8rem_2.5rem] items-center gap-2">
      <input
        value={item.description}
        onChange={(e) => update(item.id, { description: e.target.value })}
        aria-label="Description"
        className="rounded-md border px-2 py-1"
      />
      <input
        type="number"
        value={item.quantity}
        onChange={(e) => update(item.id, { quantity: Number(e.target.value) })}
        aria-label="Quantity"
        className="rounded-md border px-2 py-1 text-right"
      />
      <span className="text-right tabular-nums">{item.amountFormatted}</span>
      <button type="button" onClick={() => remove(item.id)} className="rounded p-1 hover:bg-muted">
        <TrashIcon className="h-4 w-4" />
      </button>
    </div>
  );
}

