import type { CommandModule } from 'yargs';
import { api } from '../lib/api';

type Args = { id: string; to?: string };

export const invoicesSend: CommandModule<{}, Args> = {
  command: 'invoices send <id>',
  describe: 'Email an invoice to its client',
  builder: (y) => y.positional('id', { type: 'string', demandOption: true }).option('to', { type: 'string' }),
  handler: async ({ id, to }) => {
    if (!/^inv_[a-z0-9]{10,}$/.test(id)) throw new Error(`invalid invoice id: ${id}`);
    if (to && !to.includes('@')) throw new Error(`invalid email: ${to}`);
    await api.post(`/v1/invoices/${id}/send`, { to });
    console.log(`Sent ${id}`);
  },
};

